import React, { useEffect, useState } from 'react';
import Feedback from './Feedback';
import Donate from './Donate';
import Volunteer from './Volunteer';
import AchievementsPanel from './AchievementsPanel';
import UserProfileCard from './UserProfileCard';

export default function VolunteerDonorSection({ me = {}, events = [], token, setMsg, activities }) {

  const [achievements, setAchievements] = useState(null);
  const [myNgos, setMyNgos] = useState([]);
  const [selectedNgo, setSelectedNgo] = useState(null);

  // --- User profile fetch only (new) ---
  const [profile, setProfile] = useState(null);
  const [userActivities, setUserActivities] = useState([]);

  useEffect(() => {
    if (!token) return;

    (async () => {
      try {
        const res = await fetch(
          (process.env.REACT_APP_API || "http://localhost:4000") + "/api/auth/me",
          { headers: { Authorization: `Bearer ${token}` } }
        );

        if (!res.ok) throw new Error("Failed to fetch profile");

        const data = await res.json();
        setProfile(data);
        setUserActivities(data.activities || []);

      } catch (err) {
        console.error(err);
        setMsg("Failed to load profile");
      }
    })();
  }, [token]);

  // --- Load achievements (unchanged) ---
  useEffect(() => {
    if (!token) return;

    fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/achievements', {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(r => r.json())
      .then(d => setAchievements(d || { badges: [] }))
      .catch(() => setAchievements({ badges: [] }));
  }, [token]);

  // --- Load user's NGOs (unchanged) ---
  async function loadMyNgos() {
    if (!token) { setMsg('Please login'); return; }

    try {
      const res = await fetch(
        (process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/my-ngos',
        { headers: { Authorization: `Bearer ${token}` } }
      );

      if (!res.ok) throw new Error('Failed to load your NGOs');

      const d = await res.json();

      const filtered = (d?.ngos || []).filter(n =>
        (n.role || n.user_role || "").toLowerCase().trim() !== "administrator"
      );

      setMyNgos(filtered);

    } catch (err) {
      console.error(err);
      setMsg(err.message || 'Error loading your NGOs');
    }
  }

  // --- Load details for selected NGO (unchanged) ---
  async function viewNgoDetails(id) {
    if (!token) { setMsg('Please login'); return; }

    const res = await fetch(
      (process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/ngo/' + id,
      { headers: { Authorization: `Bearer ${token}` } }
    );

    const d = await res.json();
    setSelectedNgo({
      ngo: d?.ngo || {},
      events: d?.events || [],
      donations: d?.donations || []
    });
  }

  return (
    <div className="panel" style={{ display: 'flex', gap: 20, padding: 20, alignItems: 'flex-start' }}>

      {/* LEFT PANEL */}
      <div style={{ width: 320, flexShrink: 0 }}>
        <UserProfileCard me={profile} activities={userActivities} />

        <div style={{ marginTop: 16 }}>
          <AchievementsPanel token={token} me={me} setMsg={setMsg} />
        </div>
      </div>

      {/* MIDDLE PANEL (unchanged) */}
      <div style={{ flex: 1 }}>
        <h3 style={{ marginBottom: 8 }}>Recognition & Actions</h3>

        <div style={{
          background: "#fff",
          padding: "14px 16px",
          borderRadius: 12,
          boxShadow: "0 4px 16px rgba(0,0,0,0.06)",
          marginBottom: 20,
          border: "1px solid #f3f3f3"
        }}>
          <p style={{ margin: 0, fontSize: 15 }}>
            <strong>{profile?.name || "Unknown"}</strong>
            <span style={{ color: "#888" }}> — Level:</span>{" "}
            <strong style={{ color: "#0057D9" }}>
              {profile?.points >= 200 ? "Gold"
                : profile?.points >= 100 ? "Silver"
                : profile?.points >= 50 ? "Bronze"
                : profile?.points >= 10 ? "Member" : "New"}
            </strong>
          </p>
        </div>

        <div style={{
          background: "#fff",
          padding: 18,
          borderRadius: 14,
          boxShadow: "0 4px 16px rgba(0,0,0,0.05)",
          border: "1px solid #f2f2f2"
        }}>
          <h4 style={{ marginTop: 0 }}>Give Feedback</h4>
          <Feedback token={token} setMsg={setMsg} />

          <h4 style={{ marginTop: 18 }}>Donate</h4>
          <Donate token={token} setMsg={setMsg} />

          <h4 style={{ marginTop: 18 }}>Volunteer for Event</h4>
          <Volunteer token={token} events={events} setMsg={setMsg} />
        </div>
      </div>

      {/* RIGHT PANEL (unchanged) */}
      <div style={{ width: 340, flexShrink: 0 }}>
        <h4>Your NGOs</h4>

        <button
          onClick={loadMyNgos}
          style={{
            marginBottom: 12,
            padding: "8px 12px",
            background: "#0057D9",
            color: "white",
            border: "none",
            borderRadius: 8,
            cursor: "pointer",
            fontWeight: 500,
            transition: "0.2s",
            width: "100%"
          }}
        >
          View Hosting NGOs
        </button>

        {myNgos.length > 0 ? (
          <div style={{
            background: "#fff",
            padding: 12,
            borderRadius: 12,
            boxShadow: "0 2px 10px rgba(0,0,0,0.04)",
            marginBottom: 16,
            border: "1px solid #f0f0f0"
          }}>
            {myNgos.map((ngo) => (
              <div
                key={ngo.id}
                onClick={() => viewNgoDetails(ngo.id)}
                style={{
                  padding: 10,
                  borderBottom: "1px solid #eee",
                  cursor: "pointer",
                  fontWeight: 500,
                  transition: "0.2s",
                  borderRadius: 6
                }}
                onMouseEnter={e => e.currentTarget.style.background = "#f7faff"}
                onMouseLeave={e => e.currentTarget.style.background = "transparent"}
              >
                {ngo.name}
              </div>
            ))}
          </div>
        ) : (
          <div style={{
            background: "#fff",
            padding: 12,
            borderRadius: 10,
            marginBottom: 16,
            border: "1px solid #f0f0f0"
          }}>
            <em>No NGOs loaded yet. Click “View Hosting NGOs”.</em>
          </div>
        )}

        <h4>Details</h4>

{selectedNgo ? (
  <div
    style={{
      background: "#fff",
      padding: 14,
      borderRadius: 12,
      boxShadow: "0 2px 12px rgba(0,0,0,0.05)",
      border: "1px solid #f0f0f0"
    }}
  >
    {/* NGO NAME */}
    <h5 style={{ marginTop: 0 }}>
      {selectedNgo?.ngo?.name || "Unknown NGO"}
    </h5>

    {/* NGO EMAIL */}
    <div style={{ fontSize: 14, color: "#666" }}>
      {selectedNgo?.ngo?.email || "No email available"}
    </div>

    {/* PARTICIPATION BLOCK */}
    <div style={{ marginTop: 14 }}>
      <strong>Your Participation</strong>

      {selectedNgo?.participation?.length > 0 ? (
        selectedNgo.participation.map((p) => (
          <div
            key={p.id}
            style={{
              padding: 8,
              borderBottom: "1px solid #f0f0f0",
              fontSize: 14
            }}
          >
            <div>
              <strong>Activity:</strong> {p.type}
            </div>
            <div>
              <strong>Details:</strong> {p.event_title}
            </div>
            <div>
              <strong>Date:</strong>{" "}
              {new Date(p.participated_on).toDateString()}
            </div>
          </div>
        ))
      ) : (
        <div>No participation yet.</div>
      )}
    </div>
  </div>
) : (
  <div>Select an NGO to view details.</div>
)}

      </div>
    </div>
  );
}
